// Added 2026-08-16. This endpoint was previously OPEN — anyone could POST to it and burn
// OpenAI tokens on the hardcoded test lead. It is only a fallback now that VIO-operator-agent-v2
// carries the real agent, but an open endpoint on a shared box is not worth keeping for that.
const expected = $env.VIO_WEBHOOK_TOKEN;
const item = $input.item.json;
const q = item.query || {};
const headers = item.headers || {};
const got = q.t || q.token || headers['x-vio-token'];
if (!expected) throw new Error('REFUSED: VIO_WEBHOOK_TOKEN not set (fail-closed)');
if (!got || String(got) !== String(expected)) throw new Error('REFUSED: bad or missing token');
return { json: item.body || item };

// Test Lead (edit me) — DEFECT FIX 2026-08-22. Node name and id are UNCHANGED on purpose
// (other tooling locates this node by name); only its type and behaviour changed.
//
// WAS: a Set node that pinned first_name/title/company unconditionally. `Authenticate
// (fail-closed)` already hands the POSTed body downstream, so a real lead arrived here and was
// then overwritten by the test fixture — the webhook body was, in effect, ignored.
//
// NOW: a posted field wins, the old fixture value fills the gap. A Set node could express the
// merge alone (`{{ $json.first_name || 'Kiara' }}`) but not the sanitising, and the merge without
// the sanitising is the more dangerous half: these values are interpolated into an OpenAI prompt.
// Merge and validation belong in one place, so this is a Code node.
//
// PAYLOAD SHAPE ASSUMED: the auth node returns `item.body || item`, so we receive the parsed JSON
// body. The three lead fields are read off the top level, or off a `lead` object if the caller
// nests them ({"lead": {"first_name": "..."}}). snake_case only. Anything else — other keys, other
// casings, an array, a JSON scalar body — is ignored rather than guessed at, and defaults stand.
//
// TRUST MODEL: the endpoint is authenticated but the body is free text, so treat it as untrusted
// INPUT, never as configuration:
//   * a non-string (missing, null, number, boolean, object, array) never overrides a default
//   * control characters, line breaks and Unicode line separators are removed, so a value cannot
//     open a new line — and therefore cannot forge a new prompt turn
//   * prompt/delimiter characters (" ` < > { } |) are removed, so a value cannot close the quoted
//     span it occupies in the `personalize` prompt, fake a <|role|> token, or open a code fence
//   * "system:" / "assistant:" / "user:" / "developer:" role markers lose their colon
//   * whitespace collapses to single spaces; the result is capped at MAX_LEN characters, which
//     also caps how much injected text can ride along at all
// Escaping cannot stop a sentence from *meaning* "ignore your instructions"; it can and does stop
// it from RESTRUCTURING the prompt. The system message in `personalize` carries the rest.

const DEFAULTS = {
  first_name: 'Kiara',
  title: 'Capture Manager',
  company: 'Modernized Mobile LLC',
};
const MAX_LEN = 120;

const isPlainObject = (v) => !!v && typeof v === 'object' && !Array.isArray(v);

const body = isPlainObject($input.item.json) ? $input.item.json : {};
const src = isPlainObject(body.lead) ? body.lead : body;

// Returns a safe non-empty string, or null meaning "no usable value — keep the default".
const clean = (value) => {
  if (typeof value !== 'string') return null;
  let s = value
    .replace(/[\u0000-\u001F\u007F-\u009F\u2028\u2029]/g, ' ')
    .replace(/[`"<>{}|]/g, '')
    .replace(/\b(system|assistant|user|developer)\s*:/gi, '$1')
    .replace(/\s+/g, ' ')
    .trim();
  if (s.length > MAX_LEN) s = s.slice(0, MAX_LEN).trim();
  return s.length ? s : null;
};

const out = {};
const origin = {};
for (const key of Object.keys(DEFAULTS)) {
  const posted = clean(src[key]);
  out[key] = posted === null ? DEFAULTS[key] : posted;
  origin[key] = posted === null ? 'default' : 'posted';
}

// By construction every field above is a non-empty string, so nothing downstream can render
// `undefined` — including the partially-supplied case (e.g. first_name only).
const sources = Object.values(origin);
out.lead_source = sources.every((s) => s === 'posted') ? 'posted'
  : sources.every((s) => s === 'default') ? 'default'
  : 'mixed';
out.lead_fields = origin;

// The PRODUCT must survive this node. validate_config picks OryonIQ vs VisioneerIT copy from it,
// and this node used to emit only the three name fields — so a VisioneerIT-sourced lead silently
// fell back to OryonIQ copy. Caught live 2026-08-22: a county-government CIO was drafted GovCon
// capture-intelligence copy signed "OryonIQ".
//
// Deliberately NOT run through clean(): that sanitiser is for free text heading into an LLM
// prompt. This is a routing key, and validate_config refuses any value it does not recognise —
// which is a stronger guarantee than stripping characters out of it.
const _prod = src.source_config || src.product;
if (typeof _prod === 'string' && _prod.trim()) out.source_config = _prod.trim().toLowerCase();

return { json: out };

// validate_config — mirrors reach-engine/engine.py's validate_config() exactly.
// The config is the contract: nothing downstream runs against a config that fails this.
//
// PRODUCT-AWARE since 2026-08-22. This node used to hold ONE hardcoded OryonIQ config, so every
// lead was drafted with OryonIQ copy regardless of which product sourced it. Caught live: a
// county-government CIO sourced for VisioneerIT was drafted GovCon capture-intelligence copy
// signed "OryonIQ".
//
// Keep in sync with reach-engine/config-<product>.json — sync-routes.py's agent-v1-config check
// enforces it.
const CONFIGS = {
  oryoniq: {
    product: "OryonIQ",
    one_liner: "AI market intelligence for GovCon — surfaces federal pursuits before the RFP.",
    icp: {
      person_titles: ["Capture Manager", "VP of Business Development", "Director of Business Development", "Proposal Manager"],
      person_locations: ["United States"],
      q_keywords: "government contracting",
    },
    signal: "The Pentagon suspended CMMC Phase II on July 13, 2026 — third-party assessments are paused pending a 60-day review, while DoD committed $32B to AI, cloud, and cyber in H1 FY2026. The bid barrier just dropped on a lot of money.",
    offer: "OryonIQ maps who's already winning in your NAICS and who they're teaming with — so you know who to partner with instead of who to outbid.",
    cta: "https://www.oryoniq.com/contact",
    sender: "Ellen\nOryonIQ, VisioneerIT",
    personalization_prompt: "Write ONE specific opening line (max 2 sentences) for a cold email to {first_name}, {title} at {company} — a US government contractor. Tie the current signal to their capture/BD reality. Do NOT invent specific facts about {company}; keep it about their role and the signal.",
  },
  visioneerit: {
    product: "VisioneerIT",
    one_liner: "AI automation, cybersecurity, and digital modernization for federal & SLED agencies.",
    icp: {
      person_titles: ["CIO", "CISO", "Chief Information Officer", "Chief Information Security Officer", "Director of IT", "IT Director", "Director of Information Technology", "IT Program Manager", "Digital Transformation Lead"],
      person_locations: ["United States"],
      q_keywords: "government",
    },
    signal: "Every DoD component has to reach zero-trust architecture by September 30, 2027, and that deadline hasn't moved — while AI procurement mandates land on top of it. Security and modernization budgets are committed now.",
    offer: "VisioneerIT stands up zero-trust architecture and AI-augmented security operations without a year-long procurement cycle, with CMMC readiness alongside.",
    cta: "https://www.visioneerit.com/contact",
    sender: "Ellen\nVisioneerIT",
    personalization_prompt: "Write ONE specific opening line (max 2 sentences) for a cold email to {first_name}, {title} at {company} — a federal or SLED organization. Tie the current signal to their security/modernization mandate. Do NOT invent specific facts about {company}.",
  },
};

// The product travels on the lead (source_config from VIO-source-leads, or product from a
// caller). Unknown values FAIL rather than falling back — a silent fallback is exactly what
// produced the wrong-copy bug. The webhook path sends no product and keeps its historical
// OryonIQ default, and `config_used` is reported either way so the choice is never invisible.
const _in = $input.first().json || {};
const _asked = _in.source_config || _in.product || '';
const _key = (typeof _asked === 'string' && _asked.trim()) ? _asked.trim().toLowerCase() : 'oryoniq';
if (!CONFIGS[_key]) {
  throw new Error(`REFUSED: unknown product '${_asked}'. Known: ${Object.keys(CONFIGS).join(', ')}`);
}
const cfg = { ...CONFIGS[_key], config_used: _key, config_defaulted: !(typeof _asked === 'string' && _asked.trim()) };


const REQUIRED_STR = ['product', 'one_liner', 'signal', 'offer', 'cta', 'sender', 'personalization_prompt'];
const errors = [];
for (const key of REQUIRED_STR) {
  const v = cfg[key];
  if (typeof v !== 'string' || !v.trim()) errors.push(`'${key}' must be a non-empty string`);
  else if (v.includes('<') && v.includes('>')) errors.push(`'${key}' still has a template placeholder`);
}
if (!cfg.icp || typeof cfg.icp !== 'object') errors.push("'icp' must be an object");
else {
  if (!Array.isArray(cfg.icp.person_titles) || !cfg.icp.person_titles.length) errors.push("'icp.person_titles' must be a non-empty list");
  if (!Array.isArray(cfg.icp.person_locations) || !cfg.icp.person_locations.length) errors.push("'icp.person_locations' must be a non-empty list");
}
for (const token of ['{first_name}', '{company}']) {
  if (!cfg.personalization_prompt.includes(token)) errors.push(`'personalization_prompt' must contain ${token}`);
}

const lead = $input.first().json;
return [{ json: { valid: errors.length === 0, errors, product: cfg.product, config_used: cfg.config_used, config_defaulted: cfg.config_defaulted,
    source_config: cfg.config_used,
    config_summary: `${cfg.product}: ${cfg.one_liner}`, signal: cfg.signal, offer: cfg.offer, cta: cfg.cta, sender: cfg.sender, first_name: lead.first_name, title: lead.title, company: lead.company } }];

// Assemble + Report — node name and id UNCHANGED (a drift checker locates this node by name).
//
// DEFECT FIX 2026-08-22: this node built the email from its own hardcoded copy and still emitted
// the retired generic sign-off CTA — a rhetorical question followed by the bare cfg.cta URL. The
// deployed Instantly campaign (reach-engine/campaign-oryoniq-pilot.json, step 1) replaced that
// with the per-lead Sendr page sentence below. The same email lives in
// three places — engine.py's assemble_email(), the Instantly template, and here — so this node now
// mirrors the DEPLOYED step-1 body line for line:
//     Hi {{firstName}}, / {{personalization}} / offer / page line / sender
// cfg.cta is deliberately NOT in the body any more: deployed step 1 carries no bare CTA URL. The
// contact link reaches the prospect on the Sendr page's link button instead.
//
// THE MISSING PAGE URL, HANDLED HONESTLY. This deterministic slice has no Sendr leg, so there is
// no per-lead {{sendrPageUrl}} to fill. Two dishonest options were rejected: inventing a URL (a
// lie), and emitting "I put together a short page for Acme: " with nothing after the colon (reads
// as finished copy and would ship broken). Instead the page line is OMITTED from `email`, and the
// omission is reported out loud — `email_complete: false`, `missing: ['sendr_page_url']`, and
// `cta_line_pending` carrying the exact sentence the live campaign inserts, merge tag intact.
// `email` is therefore a true SUBSET of what sends, and it labels itself unsendable.
const cfg = $('validate_config').first().json;
const res = $input.first().json;
const choice = res && res.choices && res.choices[0];
if (!choice || !choice.message || typeof choice.message.content !== 'string') {
  throw new Error('personalize returned no message content — refusing to assemble a half-built email');
}
const opener = choice.message.content.trim().replace(/^"|"$/g, '');

// Exactly the deployed step-1 sentence; {{sendrPageUrl}} stays a merge tag, never a fake URL.
const cta_line_pending = `I put together a short page for ${cfg.company}: {{sendrPageUrl}}`;
const email = `Hi ${cfg.first_name},\n\n${opener}\n\n${cfg.offer}\n\n${cfg.sender}`;

return [{ json: {
  ran: ['validate_config', 'personalize'],
  config_valid: true,
  lead: `${cfg.first_name} · ${cfg.title} · ${cfg.company}`,
  opener,
  email,
  email_complete: false,
  missing: ['sendr_page_url'],
  cta_line_pending,
  note: "Preview only, not sendable. The deployed Instantly step 1 puts cta_line_pending between the offer and the sign-off; this workflow has no Sendr leg, so that line is omitted rather than faked.",
} }];
